package com.spaceagent.platform.runtime;import com.spaceagent.platform.runtime.domain.SupervisorShadowComparison;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class SupervisorShadowComparisonTest {@Test void classifiesWithoutExecutingCandidate(){var match=SupervisorShadowComparison.classify("COMPLETED","sha256:a","COMPLETED","sha256:a",false);assertThat(match.outcome()).isEqualTo(SupervisorShadowComparison.Outcome.MATCH);assertThat(match.providerCandidateExecuted()).isFalse();assertThat(SupervisorShadowComparison.classify("COMPLETED","sha256:a","HANDOFF","sha256:a",false).outcome()).isEqualTo(SupervisorShadowComparison.Outcome.COMMAND_KIND_MISMATCH);assertThat(SupervisorShadowComparison.classify("COMPLETED","sha256:a","COMPLETED","sha256:b",false).outcome()).isEqualTo(SupervisorShadowComparison.Outcome.INPUT_HASH_MISMATCH);assertThat(SupervisorShadowComparison.classify("COMPLETED","sha256:a","COMPLETED","sha256:a",true).outcome()).isEqualTo(SupervisorShadowComparison.Outcome.UNKNOWN_CANDIDATE);}}
